parameters.text:
=You are an intake assistant for a lost & found matching system. Read the raw report below and return ONLY a JSON object (no markdown, no commentary) with these fields:

- category (string, e.g. "backpack", "phone", "jewelry", "document", "other")
- color (string, primary color, empty string if unknown)
- brand (string, empty string if unknown)
- distinguishingFeatures (short string, key identifying details)
- locationNormalized (short string, cleaned-up location name)
- dateNormalized (string, ISO date if determinable, else empty string)
- cleanDescription (string, a clear one-sentence description)
- isValid (boolean, true only if reportType, a usable description, location, and a contact email are all present)
- missingFields (array of strings, names of any required fields that are missing or unusable)

Raw report:
Report Type: {{ $json.reportType }}
Description: {{ $json.itemDescription }}
Location: {{ $json.location }}
Date: {{ $json.dateLostFound }}
Contact Name: {{ $json.contactName }}
Contact Email: {{ $json.contactEmail }}

parameters.jsCode:
// Safely parse the AI's structured JSON output and merge with the original report
const item = $input.item.json;
const raw = item.output || item.text || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { isValid: false, missingFields: ['unparseable_ai_response'] };
}

const original = $('Prepare Report Context').item.json;

return {
  json: {
    ...original,
    category: parsed.category || '',
    color: parsed.color || '',
    brand: parsed.brand || '',
    distinguishingFeatures: parsed.distinguishingFeatures || '',
    locationNormalized: parsed.locationNormalized || original.location,
    dateNormalized: parsed.dateNormalized || original.dateLostFound,
    cleanDescription: parsed.cleanDescription || original.itemDescription,
    isValid: !!parsed.isValid && !!original.contactEmail,
    missingFields: parsed.missingFields || []
  }
};

// Convert raw sheet rows into candidate report objects,
// keeping only pending reports of the opposite type
const newReport = $('JS - Parse AI Normalization').first().json;
const oppositeType = newReport.reportType === 'lost' ? 'found' : 'lost';

const rows = ($input.first().json.values) || [];

const candidates = rows.map(row => ({
  requestId: row[0] || '',
  reportType: (row[3] || '').toLowerCase(),
  category: row[4] || '',
  color: row[5] || '',
  brand: row[6] || '',
  location: row[7] || '',
  dateLostFound: row[8] || '',
  description: row[9] || '',
  contactName: row[10] || '',
  contactEmail: row[11] || '',
  status: (row[14] || '').toLowerCase()
})).filter(c => c.reportType === oppositeType && c.status === 'pending' && c.contactEmail);

if (candidates.length === 0) {
  return [{ json: { ...newReport, noCandidates: true } }];
}

return candidates.map(c => ({ json: { ...newReport, candidate: c } }));

parameters.pythonCode:
# Composite match scoring algorithm
# Score = category(40) + color(20) + brand(20) + location(10) + date proximity(10)
from datetime import datetime

item = _input.item['json']

if item.get('noCandidates'):
    return {**item, 'compositeScore': 0, 'candidate': None}

candidate = item.get('candidate', {})

def norm(s):
    return (s or '').strip().lower()

score = 0.0

# Category match (exact or substring)
newCat, candCat = norm(item.get('category')), norm(candidate.get('category'))
if newCat and candCat and (newCat == candCat or newCat in candCat or candCat in newCat):
    score += 40

# Color match
newColor, candColor = norm(item.get('color')), norm(candidate.get('color'))
if newColor and candColor and newColor == candColor:
    score += 20

# Brand match
newBrand, candBrand = norm(item.get('brand')), norm(candidate.get('brand'))
if newBrand and candBrand and newBrand == candBrand:
    score += 20
elif not newBrand and not candBrand:
    score += 5  # neither report specifies a brand; slight neutral credit

# Location match (exact or substring)
newLoc, candLoc = norm(item.get('locationNormalized')), norm(candidate.get('location'))
if newLoc and candLoc and (newLoc == candLoc or newLoc in candLoc or candLoc in newLoc):
    score += 10

# Date proximity (within 3 days = full credit, within 7 = half credit)
dateScore = 0
try:
    d1 = datetime.fromisoformat(str(item.get('dateNormalized'))[:10])
    d2 = datetime.fromisoformat(str(candidate.get('dateLostFound'))[:10])
    daysApart = abs((d1 - d2).days)
    if daysApart <= 3:
        dateScore = 10
    elif daysApart <= 7:
        dateScore = 5
except Exception:
    dateScore = 0
score += dateScore

return {
    **item,
    'compositeScore': round(score, 2)
}

parameters.jsCode:
// Pick the highest-scoring candidate and decide if it's confident enough
const MATCH_THRESHOLD = 75;
const items = $input.all().map(i => i.json);

items.sort((a, b) => (b.compositeScore || 0) - (a.compositeScore || 0));

const top = items[0] || {};
const bestMatch = top.candidate || null;
const bestScore = top.compositeScore || 0;

return [{
  json: {
    ...top,
    bestMatch,
    bestScore,
    isConfidentMatch: !!bestMatch && bestScore >= MATCH_THRESHOLD
  }
}];

parameters.text:
=You are a lost & found matching assistant. A confident match has been found between two reports.

Claim Reference: {{ $json.requestId }}
Match Score: {{ $json.bestScore }}/100

New Report ({{ $json.reportType }}):
- Item: {{ $json.cleanDescription }}
- Category: {{ $json.category }}, Color: {{ $json.color }}, Brand: {{ $json.brand }}
- Location: {{ $json.locationNormalized }}
- Date: {{ $json.dateNormalized }}

Matched Report ({{ $json.bestMatch.reportType }}):
- Item: {{ $json.bestMatch.description }}
- Category: {{ $json.bestMatch.category }}, Color: {{ $json.bestMatch.color }}, Brand: {{ $json.bestMatch.brand }}
- Location: {{ $json.bestMatch.location }}
- Date: {{ $json.bestMatch.dateLostFound }}

Write a short, warm, reassuring email body (under 150 words) telling the recipient a likely match has been found for their item. Include the claim reference number, a brief description of the matched item, and a next step to verify ownership at the desk before pickup or return. Do NOT include any disclaimers about being an AI, and do NOT invent contact details.

