// Build two SendGrid email payloads: one for each matched party
const item = $input.first().json;
const messageBody = item.output || item.response || item.text ||
  `Good news — we believe we found a match for your item (Claim Reference: ${item.requestId}). Please visit the desk to verify and complete the handoff.`;

const subject = `Lost & Found Match Found — Claim #${item.requestId}`;

return [{
  json: {
    ...item,
    emailSubject: subject,
    emailBody: messageBody,
    toOriginalReporter: item.contactEmail,
    toMatchedReporter: item.bestMatch ? item.bestMatch.contactEmail : '',
    logDate: new Date().toISOString().split('T')[0],
    logTimestamp: new Date().toISOString()
  }
}];

// No confident match yet — prepare this report to be logged as pending
const item = $input.first().json;

return [{
  json: {
    ...item,
    logDate: new Date().toISOString().split('T')[0],
    logTimestamp: new Date().toISOString()
  }
}];
